// AWI: label harga + schema Product halaman BYD TiTAN 7 DM (harga OTR Jakarta resmi 20 Nov 2026).
// Perbarui bila harga OTR Makassar sudah diisi di field tipe & harga model.
add_action('wp_head', function () {
	if (!is_single(10706)) return;
	echo '<style id="awi-titan-tba">.model__price>div::after{content:" Rp639 jt OTR Jakarta";font-weight:800;font-size:.82em;margin-left:4px}</style>';
	$img = wp_get_attachment_url(10847);
	$schema = array(
		'@context' => 'https://schema.org',
		'@type' => 'Product',
		'name' => 'BYD TiTAN 7 DM',
		'brand' => array('@type' => 'Brand', 'name' => 'BYD'),
		'category' => 'SUV plug-in hybrid 7 kursi',
		'url' => get_permalink(10706),
		'image' => $img ? array($img) : array(),
		'description' => 'BYD TiTAN 7 DM (sebelumnya BYD Ti7): SUV plug-in hybrid 7 kursi, varian Premium FWD DM-i dan Performance AWD DM-p, jarak listrik hingga 155 km (NEDC). Harga OTR Jakarta Rp639 juta dan Rp739 juta.',
		'offers' => array(
			'@type' => 'AggregateOffer',
			'priceCurrency' => 'IDR',
			'lowPrice' => 639000000,
			'highPrice' => 739000000,
			'offerCount' => 2,
			'availability' => 'https://schema.org/PreOrder',
			'seller' => array(
				'@type' => 'Organization',
				'name' => 'BYD Haka Karebosi Makassar',
				'telephone' => '+6282259452349',
				'address' => array('@type' => 'PostalAddress', 'streetAddress' => 'Jl. Ahmad Yani No. 15', 'addressLocality' => 'Makassar', 'addressRegion' => 'Sulawesi Selatan', 'addressCountry' => 'ID'),
			),
		),
	);
	echo '<script type="application/ld+json">' . wp_json_encode($schema, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . '</script>';
}, 99);
